import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://127.0.0.1:8125"


def get_json(path):
    url = BASE + path
    try:
        with urllib.request.urlopen(url, timeout=30) as response:
            status = response.status
            body = response.read()
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise RuntimeError(f"GET {url} failed: {exc}") from exc
    if not 200 <= status < 300:
        raise RuntimeError(f"GET {url} returned HTTP {status}: {body.decode('utf-8', 'replace')}")
    try:
        return json.loads(body)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise RuntimeError(f"GET {url} returned invalid JSON: {exc}") from exc

try:
    last = get_json("/batches/last")
    if not isinstance(last, dict) or isinstance(last.get("last_seq"), bool) or not isinstance(last.get("last_seq"), int):
        raise RuntimeError("GET /batches/last JSON does not contain integer last_seq")
    last_seq = last["last_seq"]

    result = get_json("/orders?after=" + urllib.parse.quote(str(last_seq), safe=""))
    if not isinstance(result, dict) or not isinstance(result.get("orders"), list):
        raise RuntimeError("GET /orders JSON does not contain an orders list")
    orders = result["orders"]
    if not orders:
        sys.exit(0)

    seqs = []
    order_count = len(orders)
    total_units = 0
    total_revenue_cents = 0
    revenue_by_region_cents = {}

    for index, order in enumerate(orders):
        if not isinstance(order, dict):
            raise RuntimeError(f"order at index {index} is not an object")
        for field in ("seq", "units", "unit_price_cents"):
