            if isinstance(value, bool) or not isinstance(value, int):
                raise RuntimeError(f"order at index {index} has non-integer {field}")
        region = order.get("region")
        if not isinstance(region, str):
            raise RuntimeError(f"order at index {index} has non-string region")
        seqs.append(order["seq"])
        total_units += order["units"]
        revenue = order["units"] * order["unit_price_cents"]
        total_revenue_cents += revenue
        revenue_by_region_cents[region] = revenue_by_region_cents.get(region, 0) + revenue

    batch = {
        "batch_start_seq": min(seqs),
        "batch_end_seq": max(seqs),
        "order_count": order_count,
        "total_units": total_units,
        "total_revenue_cents": total_revenue_cents,
        "revenue_by_region_cents": revenue_by_region_cents,
    }
    data = json.dumps(batch, separators=(",", ":")).encode("utf-8")
    request = urllib.request.Request(
        BASE + "/batches",
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            status = response.status
            body = response.read()
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", "replace")
        raise RuntimeError(f"POST {BASE}/batches returned HTTP {exc.code}: {body}") from exc
